/**
 * The stop watch on one launched cloud agent, armed by `lib/watch.ts`. Every
 * fire is host-only: it polls the agent and skips while the agent runs, so
 * no model turn starts. The first fire that sees the agent stopped wakes the
 * bound conversation once and ends the watch.
 *
 * A fire never throws, because a v1 host stops firing a reminder whose
 * handler threw; every outcome is a skip or a stop.
 */
import * as z from "zod/v4";
import { CursorBackendError } from "../../../internal/cursor/backend-client.js";
import { describeError } from "../../../internal/describe-error.js";
import { defineReminder } from "../../../reminders.js";
import { cloudAgentsBackend } from "../lib/backend.js";
/** How long a watch polls before it stops without a wake. */
export const WATCH_WINDOW_HOURS = 24;
const watchArgs = z.object({
    agentId: z.string().min(1),
    deadline: z.string().datetime(),
});
const STOPPED = new Set(["finished", "error", "expired"]);
const watch = defineReminder({
    async run(fire) {
        const parsed = watchArgs.safeParse(fire.args);
        if (!parsed.success) {
            return { action: "stop" };
        }
        const { agentId, deadline } = parsed.data;
        const pastDeadline = Date.now() >= Date.parse(deadline);
        let info;
        try {
            info = await cloudAgentsBackend().info(agentId);
        }
        catch (error) {
            if (isPermanent(error)) {
                console.warn(`[cursor-cloud-agents] stopped watching ${agentId}: ${describeError(error)}`);
                return { action: "stop" };
            }
            return pastDeadline ? { action: "stop" } : { action: "skip" };
        }
        if (!STOPPED.has(info.status)) {
            return pastDeadline ? { action: "stop" } : { action: "skip" };
        }
        // At most once: a wake that failed may already have started its turn.
        try {
            await fire.followup({
                message: `[cloud agent stopped] ${agentId} is ${info.status}.\n${JSON.stringify(info)}`,
            });
        }
        catch (error) {
            console.warn(`[cursor-cloud-agents] could not wake the conversation watching ${agentId}: ${describeError(error)}`);
        }
        return { action: "stop" };
    },
});
export default watch;
/** The agent is gone or out of the host key's reach; polling will not bring it back. */
function isPermanent(error) {
    return error instanceof CursorBackendError && (error.status === 403 || error.status === 404);
}
